@push('scripts')<script>document.querySelectorAll('[data-tuition-payment]').forEach((form)=>{const method=form.querySelector('[data-payment-method]'),box=form.querySelector('[data-qr-box]'),image=form.querySelector('[data-qr-image]'),download=form.querySelector('[data-download-qr]'),amount=form.querySelector('[data-qr-amount]');const refresh=()=>{image.src=`https://img.vietqr.io/image/970428-683939339-compact2.png?amount=${encodeURIComponent(amount.value)}&addInfo=${encodeURIComponent(form.dataset.qrContent)}&accountName=${encodeURIComponent('PHAN HIEU TRUONG DAI HOC BINH DUONG TAI CA MAU')}`;download.href=`${form.dataset.qrDownload}?amount=${encodeURIComponent(amount.value)}`};method.addEventListener('change',()=>{box.classList.toggle('d-none',method.value!=='transfer');if(method.value==='transfer')refresh()});form.querySelector('[data-create-qr]').addEventListener('click',refresh);amount.addEventListener('change',()=>{if(method.value==='transfer')refresh()})});</script>@endpush
